def quicksort(arr):
    """
    Sorts an array of integers using the QuickSort algorithm.

    Parameters:
    arr (list): A list containing integers to be sorted.

    Returns:
    list: The sorted list of integers.
    """
    if len(arr) <= 1:
        return arr

    pivot = arr[0]  # Find the first element in the array and use it for the pivot
    less_than_pivot = []  # Initialize a list to store all elements less than the pivot
    greater_than_pivot = []  # Initialize a list to store all elements greater than the pivot

    for num in arr:
        if num < pivot:
            less_than_pivot.append(num)
        else:
            greater_than_pivot.append(num)

    return quicksort(less_than_pivot) + [pivot] + quicksort(greater_than_pivot)

